//! Curve25519: X25519 key agreement (RFC 7748) and Ed25519 signatures
//! (RFC 8032).
//!
//! Layout:
//!
//! * `field` — GF(2^255 - 19), portable radix-2^51 limbs (constant time).
//! * `x86_adx` — x86-64 radix-2^64 field arithmetic with BMI2/ADX for the
//!   X25519 ladder (run-time dispatch).
//! * `scalar` — arithmetic modulo the group order `L` (Montgomery form).
//! * `edwards` — edwards25519 group: constant-time fixed-base comb and
//!   variable-time double-scalar multiplication for verification.
//! * `table` — precomputed multiples of the base point, generated by the
//!   ignored unit test `edwards::tests::regenerate_tables`; the test
//!   `tables_are_reproducible` recomputes the whole file, so a stale or
//!   corrupted table fails. (The data was also cross-checked byte for byte
//!   against an independent big-integer affine implementation in Python.)
//! * [`x25519`] and [`ed25519`] — the public APIs.

mod edwards;
mod field;
mod scalar;
mod table;
#[cfg(target_arch = "x86_64")]
mod x86_adx;

pub mod ed25519;
pub mod x25519;
